def max_sum(arr):
    n = len(arr)

    # Step 1: Compute Increasing Subsequence (LIS) Sum
    inc = arr[:]  # Initialize with the elements of the array
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Step 2: Compute Decreasing Subsequence (LDS) Sum
    dec = arr[:]  # Initialize with the elements of the array
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # Step 3: Find Maximum Bitonic Subsequence Sum
    max_bitonic_sum = 0
    for i in range(n):
        max_bitonic_sum = max(max_bitonic_sum, inc[i] + dec[i] - arr[i])

    return max_bitonic_sum

# Example Test
assert max_sum([1, 15, 51, 45, 33, 100, 12, 18, 9]) == 194
