def get_median(arr1, arr2, n):
    """
    Function to find the median of two sorted arrays of the same size.
    :param arr1: First sorted list
    :param arr2: Second sorted list
    :param n: Size of each list
    :return: The median as a float
    """
    if n <= 0:
        return None
    if n == 1:
        return (arr1[0] + arr2[0]) / 2.0
    if n == 2:
        return (max(arr1[0], arr2[0]) + min(arr1[1], arr2[1])) / 2.0

    # Calculate medians
    m1 = arr1[n // 2] if n % 2 != 0 else (arr1[n // 2] + arr1[n // 2 - 1]) / 2.0
    m2 = arr2[n // 2] if n % 2 != 0 else (arr2[n // 2] + arr2[n // 2 - 1]) / 2.0

    # If medians are equal, return either
    if m1 == m2:
        return m1

    # If m1 < m2, then median must be in arr1[n//2:] and arr2[:n//2]
    if m1 < m2:
        if n % 2 == 0:
            return get_median(arr1[n // 2 - 1:], arr2[:n // 2 + 1], n // 2 + 1)
        return get_median(arr1[n // 2:], arr2[:n // 2 + 1], n // 2 + 1)

    # If m1 > m2, then median must be in arr1[:n//2] and arr2[n//2:]
    if n % 2 == 0:
        return get_median(arr2[n // 2 - 1:], arr1[:n // 2 + 1], n // 2 + 1)
    return get_median(arr2[n // 2:], arr1[:n // 2 + 1], n // 2 + 1)
