def jacobsthal_num(n):
    # Base cases
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Recursive formula for Jacobsthal numbers
    return jacobsthal_num(n - 1) + 2 * jacobsthal_num(n - 2)

# Example usage and test case
assert jacobsthal_num(5) == 11
```

