def mul_even_odd(numbers):
    even_found = False
    odd_found = False
    first_even = None
    first_odd = None

    for num in numbers:
        if not even_found and num % 2 == 0:
            first_even = num
            even_found = True
        if not odd_found and num % 2 != 0:
            first_odd = num
            odd_found = True
        if even_found and odd_found:
            break

    if first_even is not None and first_odd is not None:
        return first_even * first_odd
    else:
        return None

# Example usage:
# assert mul_even_odd([1,3,5,7,4,1,6,8]) == 4
```

